import{_ as a,a as s,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第二册：实践与进步 · 综合复习与自测 · 第1–9课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第二册：实践与进步 · 综合复习与自测 · 第1–9课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-2/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 综合复习与自测","link":"/life/english/new-concept/book-2/review"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第10–18课","link":"/life/english/new-concept/book-2/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 综合复习与自测","link":"/life/english/new-concept/book-2/review"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第10–18课","link":"/life/english/new-concept/book-2/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/review-part-01.md","filePath":"life/english/new-concept/book-2/review-part-01.md"}'),r={name:"life/english/new-concept/book-2/review-part-01.md"};function n(i,e,l,h,c,d){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-综合复习与自测-·-第1–9课" tabindex="-1">第二册：实践与进步 · 综合复习与自测 · 第1–9课 <a class="header-anchor" href="#第二册-实践与进步-·-综合复习与自测-·-第1–9课" aria-label="Permalink to &quot;第二册：实践与进步 · 综合复习与自测 · 第1–9课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第二册-实践与进步-·-综合复习与自测" tabindex="-1">第二册：实践与进步 · 综合复习与自测 <a class="header-anchor" href="#第二册-实践与进步-·-综合复习与自测" aria-label="Permalink to &quot;第二册：实践与进步 · 综合复习与自测 {#第二册-实践与进步-·-综合复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-1-·-一般过去时与事件顺序" tabindex="-1">Lesson 1 · 一般过去时与事件顺序 <a class="header-anchor" href="#lesson-1-·-一般过去时与事件顺序" aria-label="Permalink to &quot;Lesson 1 · 一般过去时与事件顺序 {#lesson-1-·-一般过去时与事件顺序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Maya closed her book quietly after the discussion.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>填入 close 的一般过去式：Maya ___ her book quietly.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> closed</p><p><strong>解析：</strong> close 规则变化加 -d，句中讲述已经发生的动作。</p></details><p><strong>表达迁移：</strong> 用三句描述一次公共场所的小打扰，包括地点、反应和解决办法。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Maya closed her book quietly after the discussion. A student nearby asked for silence. Maya moved to the entrance to finish her conversation.</p><p>第一句的组织方式：Maya 是主语，closed 是过去式谓语，her book 是宾语，quietly 是方式状语，after 短语标记时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：quiet 是形容词，quietly 是副词；closed quiet 不能表达“轻轻合上”。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-001">回看本课</a></p><h2 id="lesson-2-·-一般现在时与习惯" tabindex="-1">Lesson 2 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-2-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 2 · 一般现在时与习惯 {#lesson-2-·-一般现在时与习惯}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Leo usually eats breakfast before seven.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>选 eat/eats：Leo usually ___ breakfast before seven.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> eats</p><p><strong>解析：</strong> 第三人称单数的肯定句使用 eats。</p></details><p><strong>表达迁移：</strong> 比较自己工作日和周末的作息，至少使用两个频率副词。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Leo usually eats breakfast before seven. On Sundays he turns off his alarm. He sometimes has his first meal at eleven.</p><p>第一句的组织方式：Leo 是单数主语，eats 是习惯性动作，usually 位于实义动词前，before seven 给出时间边界。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：He usually eat 不合主谓一致；He does usually eats 中不能重复标记第三人称单数。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-002">回看本课</a></p><h2 id="lesson-3-·-动词、宾语与补足语" tabindex="-1">Lesson 3 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-3-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 3 · 动词、宾语与补足语 {#lesson-3-·-动词、宾语与补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Nina sent her uncle a postcard from the island.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>填介词：Nina sent a postcard ___ her uncle.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> to 标记 send 的接收对象。</p></details><p><strong>表达迁移：</strong> 写三句寄卡片的经历，交代收件人、寄出地和送达时间。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Nina sent her uncle a postcard from the island. She checked the address twice. The card reached him before she returned.</p><p>第一句的组织方式：Nina 是主语，sent 是 send 的过去式，her uncle 是间接宾语，a postcard 是直接宾语，from 短语说明寄出地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：send a postcard for her 表示替她寄，不一定表示寄给她；寄给她用 to her。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-003">回看本课</a></p><h2 id="lesson-4-·-现在完成时与过去时间" tabindex="-1">Lesson 4 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-4-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 4 · 现在完成时与过去时间 {#lesson-4-·-现在完成时与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Iris has visited three coastal towns this month.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>填 have 的正确形式：Iris ___ visited three towns this month.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> has</p><p><strong>解析：</strong> Iris 为第三人称单数，完成时助动词用 has。</p></details><p><strong>表达迁移：</strong> 介绍一次仍在进行的旅行，用完成时概括成果，再用过去式补充一天的细节。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Iris has visited three coastal towns this month. She visited the smallest one on Monday. She plans to return home next week.</p><p>第一句的组织方式：has visited 表示本月到现在的经历；three coastal towns 是已完成的数量，this month 在此被理解为尚未结束的时间段。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：has visited yesterday 通常不合适；yesterday 明确结束的时间应配 visited。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-004">回看本课</a></p><h2 id="lesson-5-·-现在完成时与过去时间" tabindex="-1">Lesson 5 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-5-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 5 · 现在完成时与过去时间 {#lesson-5-·-现在完成时与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Our studio has received six messages today.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>填 receive 的形式：The studio has ___ six messages.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> received</p><p><strong>解析：</strong> has 后要求过去分词 received。</p></details><p><strong>表达迁移：</strong> 描述两个团队如何传递消息，区分已经收到和准备回复的内容。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our studio has received six messages today. The last message arrived at noon. We will answer it after lunch.</p><p>第一句的组织方式：Our studio 是整体单数主语，所以用 has；six messages 表示累计结果，today 的时间范围延伸到现在。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：receive 不等于 send；已收到用 have received，不要写 have receive。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-005">回看本课</a></p><h2 id="lesson-6-·-冠词与可数性" tabindex="-1">Lesson 6 · 冠词与可数性 <a class="header-anchor" href="#lesson-6-·-冠词与可数性" aria-label="Permalink to &quot;Lesson 6 · 冠词与可数性 {#lesson-6-·-冠词与可数性}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A neighbour brought me some bread after the storm.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>选择 a/some：A neighbour brought me ___ bread.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> some</p><p><strong>解析：</strong> 这里 bread 指食物材料，不按单个计数。</p></details><p><strong>表达迁移：</strong> 描述一次邻里互助，首次和再次提及同一人物时分别使用 a 与 the。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A neighbour brought me some bread after the storm. The neighbour had helped us clear the path. We invited her to share a warm meal.</p><p>第一句的组织方式：A neighbour 首次引入人物；some bread 是不可数名词短语；brought 带 me 与 some bread 两个宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：a bread 通常不能表示“一片面包”；用 a slice of bread，特定面包种类的用法另论。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-006">回看本课</a></p><h2 id="lesson-7-·-过去进行时与叙事背景" tabindex="-1">Lesson 7 · 过去进行时与叙事背景 <a class="header-anchor" href="#lesson-7-·-过去进行时与叙事背景" aria-label="Permalink to &quot;Lesson 7 · 过去进行时与叙事背景 {#lesson-7-·-过去进行时与叙事背景}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The guards were checking the gate when the parcel arrived.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>填 was/were：The guards ___ checking the gate.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> guards 是复数主语。</p></details><p><strong>表达迁移：</strong> 写一次“赶到时已经晚了”的事件，至少包含一个背景动作。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The guards were checking the gate when the parcel arrived. The driver waited outside. By then, the visitor had already left.</p><p>第一句的组织方式：主句 were checking 是背景，when 从句 arrived 是介入事件；guards 是复数，所以不能用 was。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：The guards was checking 主谓不一致；checking 是活动，不应以 checked 代替 -ing 来构成进行时。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-007">回看本课</a></p><h2 id="lesson-8-·-比较级与比较范围" tabindex="-1">Lesson 8 · 比较级与比较范围 <a class="header-anchor" href="#lesson-8-·-比较级与比较范围" aria-label="Permalink to &quot;Lesson 8 · 比较级与比较范围 {#lesson-8-·-比较级与比较范围}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Lena&#39;s garden is smaller but neater than mine.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>填 neat 的比较级：Her garden is ___ than mine.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> neater</p><p><strong>解析：</strong> neat 是单音节形容词，比较级加 -er。</p></details><p><strong>表达迁移：</strong> 比较三个真实或虚构花园，用两个比较级和一个最高级。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Lena&#39;s garden is smaller but neater than mine. Omar&#39;s garden is the largest of the three. Lena won the prize for design.</p><p>第一句的组织方式：smaller 与 neater 是并列比较级；than mine 中 mine 代替 my garden，比较的是花园而非主人。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Her garden is neater than me 比较对象不对称；用 than mine 或 than my garden。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-008">回看本课</a></p><h2 id="lesson-9-·-一般过去时与事件顺序" tabindex="-1">Lesson 9 · 一般过去时与事件顺序 <a class="header-anchor" href="#lesson-9-·-一般过去时与事件顺序" aria-label="Permalink to &quot;Lesson 9 · 一般过去时与事件顺序 {#lesson-9-·-一般过去时与事件顺序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The crowd reached the square at half past eight.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>填 at/on/in：We met ___ half past eight.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at</p><p><strong>解析：</strong> 具体钟点前使用 at。</p></details><p><strong>表达迁移：</strong> 叙述一次等候，至少写一个钟点、一个地点及意外情况。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The crowd reached the square at half past eight. The clock above the gate was silent. A worker explained that it needed repairs.</p><p>第一句的组织方式：reached 是及物动词，后直接接 the square；at half past eight 是具体钟点，不用 in。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：reach the square 不加 to；arrive at the square 才需要 at。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-009">回看本课</a></p>',79)])])}const u=a(r,[["render",n]]);export{m as __pageData,u as default};
